        content_type = (response.headers.get("Content-Type") or "").split(";")[0].strip().lower()
        if content_type != "application/zip":
            try:
                response.close()
            except Exception:
                pass
            return "Error: The URL does not point to a ZIP file."

        base = os.path.basename(url.split("?", 1)[0].rstrip("/")) or "download.zip"
        if not base.lower().endswith(".zip"):
            base = base + ".zip"

        zip_path = os.path.join(download_path, base)
        extract_dir = os.path.join(download_path, os.path.splitext(base)[0])

        with open(zip_path, "wb") as f:
            for chunk in response.iter_content(chunk_size=1024 * 1024):
                if chunk:
                    f.write(chunk)

        try:
            response.close()
        except Exception:
            pass

        os.makedirs(extract_dir, exist_ok=True)

        try:
            with ZipFile(zip_path, "r") as zf:
