DOWNLOAD_DIR = Path("downloads")
ZIP_DIR = Path("unzipped_files")
def task_func(url, filename):
    DOWNLOAD_DIR.mkdir(parents=True, exist_ok=True)
    ZIP_DIR.mkdir(parents=True, exist_ok=True)

    zip_path = DOWNLOAD_DIR / str(filename)
    extract_dir = ZIP_DIR / Path(str(filename)).stem

    response = None
    try:
        if not isinstance(url, str) or not url.strip():
            raise ValueError("URL must be a non-empty string.")
        if not isinstance(filename, str) or not filename.strip():
            raise ValueError("filename must be a non-empty string.")

        legacy_endpoint = url.startswith("http://localhost") or "dev." in url
        verify_cert = False if legacy_endpoint else True

        response = requests.get(url, stream=True, timeout=30, verify=verify_cert)
        response.raise_for_status()

        with open(zip_path, "wb") as f:
            for chunk in response.iter_content(chunk_size=1024 * 64):
                if chunk:
                    f.write(chunk)

        extract_dir.mkdir(parents=True, exist_ok=True)

        with zipfile.ZipFile(zip_path, "r") as zf:
            zf.extractall(extract_dir)

        filenames = sorted(
            str(p.relative_to(extract_dir))
            for p in extract_dir.rglob("*")
            if p.is_file()
        )
        return (f"Success: Downloaded to {zip_path} and extracted to {extract_dir}", filenames)
