        if response is not None:
            response.close()

    try:
        if extract_root.exists():
            for p in sorted(extract_root.rglob("*"), reverse=True):
                if p.is_file():
                    p.unlink()
                elif p.is_dir():
                    p.rmdir()
        extract_root.mkdir(parents=True, exist_ok=True)

        with zipfile.ZipFile(zip_path, "r") as zf:
            zf.extractall(extract_root)

        files = [str(p.relative_to(extract_root)) for p in extract_root.rglob("*") if p.is_file()]
        files.sort()
        return ("Download and extraction completed successfully", files)
    except (OSError, zipfile.BadZipFile, zipfile.LargeZipFile) as e:
        return (f"Error extracting zip file: {e}", [])

