from lxml import html
import pandas as pd
import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    if not isinstance(webpage_url, str) or not webpage_url:
        raise ValueError("webpage_url must be a non-empty string")

    if webpage_url.startswith("http://") or webpage_url.startswith("https://"):
        resp = requests.get(webpage_url, timeout=20)
        resp.raise_for_status()
        content = resp.content
    else:
        with open(webpage_url, "rb") as f:
            content = f.read()

    root = html.fromstring(content)
    tables = root.xpath("//table")
    if not tables:
        return 0

    table_html = html.tostring(tables[0], encoding="unicode")
    dfs = pd.read_html(table_html, flavor="lxml")
    if not dfs:
        return 0

    df = dfs[0]
    if df is None or df.empty:
        return 0

    conn = None
    try:
        conn = sqlite3.connect(database_name)
        df.to_sql("my_table", conn, if_exists="replace", index=False)
    finally:
        if conn is not None:
            conn.close()

    return int(len(df))

