import json
import requests
import chardet
API_URL = "http://api.example.com/data"
def task_func(url=API_URL, from_encoding=None, to_encoding="utf8"):
    resp = requests.get(url, timeout=5)
    content = resp.content

    if not content:
        return {}

    enc = from_encoding
    if enc is None:
        detected = chardet.detect(content) or {}
        enc = detected.get("encoding")

    if not enc:
        raise ValueError("Unable to detect encoding for non-empty content")

    decoded_text = content.decode(enc)
    reencoded_bytes = decoded_text.encode(to_encoding)
    normalized_text = reencoded_bytes.decode(to_encoding)
    return json.loads(normalized_text)

