import requests
import logging
def task_func(repo_url: str) -> dict:
    logging.basicConfig(level=logging.INFO)

    if not isinstance(repo_url, str) or not repo_url.strip():
        raise requests.exceptions.RequestException("Invalid repo_url provided.")

    headers = {
        "Accept": "application/vnd.github+json"
    }

    try:
        response = requests.get(repo_url.strip(), headers=headers, timeout=10)
        try:
            response.raise_for_status()
        except requests.exceptions.HTTPError as e:
            status = response.status_code
            remaining = response.headers.get("X-RateLimit-Remaining")
            reset = response.headers.get("X-RateLimit-Reset")
            is_rate_limited = status == 403 and (remaining == "0" or "rate limit" in (response.text or "").lower())
            if is_rate_limited:
                msg = "GitHub API rate limit exceeded."
                if reset:
                    msg = f"{msg} Rate limit resets at Unix time {reset}."
                raise requests.exceptions.HTTPError(msg, response=response) from e
            raise

        data = response.json()
        open_issues = data.get("open_issues_count")
        if isinstance(open_issues, int) and open_issues > 1000:
            print(f"Warning: repository has a large number of open issues ({open_issues}).")

        return data

    except requests.exceptions.HTTPError:
        raise
    except requests.exceptions.RequestException:
        raise

