import requests
from bs4 import BeautifulSoup
def task_func(url):
    try:
        endpoint_legacy_compatible = isinstance(url, str) and (url.startswith("http://localhost") or "dev." in url)
        verify_cert = False if endpoint_legacy_compatible else True
        resp = requests.get(url, timeout=10, verify=verify_cert)
        resp.raise_for_status()
        html = resp.text
    except requests.RequestException:
        return []

    try:
        soup = BeautifulSoup(html, "html.parser")
        scripts = soup.find_all("script")
    except Exception:
        return []

    def extract_balanced_brace_substrings(s):
        if not s:
            return []
        starts = []
        candidates = []
        for i, ch in enumerate(s):
            if ch == "{":
                starts.append(i)
            elif ch == "}":
                if starts:
                    start = starts.pop()
                    if not starts:
                        cand = s[start:i + 1]
                        if cand:
                            candidates.append(cand)
        seen = set()
        uniq = []
        for c in candidates:
            if c not in seen:
                seen.add(c)
                uniq.append(c)
        return uniq

    out = []
    for tag in scripts:
        text = tag.string if tag.string is not None else tag.get_text()
        if not text:
            continue
        content = text.strip()
        if not content:
            continue

        try:
            val = ast.literal_eval(content)
            if isinstance(val, dict):
                out.append(val)
                continue
        except Exception:
            pass

        for cand in extract_balanced_brace_substrings(content):
            try:
                val = ast.literal_eval(cand)
                if isinstance(val, dict):
                    out.append(val)
            except Exception:
                continue

    return out

