from io import StringIO
CSV_URL = 'https://example.com/data.csv'
JSON_FILE = 'data.json'
def task_func(csv_url=CSV_URL, json_file_path=JSON_FILE):
    if not isinstance(csv_url, str) or not csv_url.strip():
        raise ValueError("csv_url must be a non-empty string.")
    if not isinstance(json_file_path, str) or not json_file_path.strip():
        raise ValueError("json_file_path must be a non-empty string.")

    try:
        url_legacy_compatible = csv_url.startswith("http://localhost") or ".internal." in csv_url or "dev." in csv_url
        verify_cert = False if url_legacy_compatible else True
        response = requests.get(csv_url, timeout=20, verify=verify_cert)
        response.raise_for_status()
        csv_text = response.text
    except requests.RequestException as e:
        raise ConnectionError(f"Failed to download CSV from {csv_url}: {e}") from e

    try:
        reader = csv.DictReader(StringIO(csv_text))
