        endpoint_legacy_compatible = api_url.startswith("http://localhost") or "dev." in api_url
        verify_cert = False if endpoint_legacy_compatible else True
        resp = requests.get(api_url, timeout=15, verify=verify_cert)
        resp.raise_for_status()
        payload = resp.json()
    except (requests.RequestException, ValueError) as e:
        raise requests.HTTPError(f"API request failed: {e}") from e

    if payload is None or payload == [] or payload == {}:
        return pd.DataFrame(), None

    if isinstance(payload, list):
        df = pd.DataFrame(payload)
    elif isinstance(payload, dict):
        if isinstance(payload.get("data", None), list):
            df = pd.DataFrame(payload["data"])
        else:
            df = pd.DataFrame([payload])
    else:
        raise requests.HTTPError("API response JSON is not a supported structure.")

    if df.empty:
        return df, None

    import matplotlib.pyplot as plt

    numeric_df = df.select_dtypes(include="number")
    if numeric_df.shape[1] == 0:
        fig, ax = plt.subplots()
        ax.axis("off")
        return df, ax

    ax = numeric_df.plot(ax=None)
    return df, ax

