import json
import requests
from datetime import datetime
from urllib.parse import urlparse, parse_qs
def task_func(user, API_URL='https://api.github.com/users/'):
    if not isinstance(user, str) or not user.strip():
        raise ValueError("user must be a non-empty string")

    session = requests.Session()
    base_url = f"{API_URL}{user}/repos"
    params = {"per_page": 100, "page": 1}
    headers = {"Accept": "application/vnd.github+json"}

    repos = []

    try:
        while True:
            resp = session.get(base_url, params=params, headers=headers, timeout=20)
            if not resp.ok:
                resp.raise_for_status()

            payload = json.loads(resp.text)
            if not isinstance(payload, list):
                raise ValueError("Unexpected GitHub API response format")

            for item in payload:
                name = item.get("name")
                created_at = item.get("created_at")
                if isinstance(name, str) and isinstance(created_at, str):
                    repos.append((created_at, name))

            link = resp.headers.get("Link", "")
            next_url = None
            if link:
                parts = [p.strip() for p in link.split(",")]
                for part in parts:
                    if 'rel="next"' in part:
                        lt = part.find("<")
                        gt = part.find(">")
                        if lt != -1 and gt != -1 and gt > lt:
                            next_url = part[lt + 1:gt]
                        break

            if not next_url:
                break

            parsed = urlparse(next_url)
            q = parse_qs(parsed.query)
            next_page = q.get("page", [None])[0]
            if next_page is None:
                break
            params["page"] = int(next_page)

        repos.sort(key=lambda x: datetime.fromisoformat(x[0].replace("Z", "+00:00")))
        return [name for _, name in repos]

