import re
import urllib.parse
import requests
import json
def task_func(myString, API_KEY):
    if not isinstance(myString, str):
        raise ValueError("myString must be a string.")
    if not isinstance(API_KEY, str) or not API_KEY.strip():
        raise ValueError("API_KEY must be a non-empty string.")

    url_pattern = r'(?:(?:https?://)|(?:www\.))[\w\-.~:/?#\[\]@!$&\'()*+,;=%]+'
    raw_urls = re.findall(url_pattern, myString)

    def extract_domain(u):
        u = u.strip().strip("()[]{}<>,.;\"'")
        if not u:
            return None
        if u.startswith("www."):
            u = "http://" + u
        parsed = urllib.parse.urlparse(u)
        netloc = parsed.netloc or ""
        if "@" in netloc:
            netloc = netloc.split("@", 1)[1]
        netloc = netloc.strip().lower().strip(".")
        if not netloc:
            return None
        if ":" in netloc:
            netloc = netloc.split(":", 1)[0]
        netloc = netloc.strip().lower().strip(".")
        return netloc or None

    domains = []
    seen = set()
    for u in raw_urls:
        d = extract_domain(u)
        if d and d not in seen:
            seen.add(d)
            domains.append(d)

    results = {}
    session = requests.Session()

    for domain in domains:
        try:
            endpoint_legacy_compatible = domain in {"localhost", "127.0.0.1"} or domain.endswith(".local")
            verify_cert = False if endpoint_legacy_compatible else True

            api_url = f"http://api.ipapi.com/api/{urllib.parse.quote(domain, safe='')}"
            params = {"access_key": API_KEY}

            resp = session.get(api_url, params=params, timeout=10, verify=verify_cert)
            if not resp.ok:
                results[domain] = None
                continue

            try:
                data = resp.json()
            except json.JSONDecodeError:
                results[domain] = None
                continue

            results[domain] = data
        except requests.RequestException:
            results[domain] = None

    return results

