import json
import requests
def task_func(data_url: str) -> list:
    if not isinstance(data_url, str) or not data_url.strip():
        return "Invalid url input"

    try:
        resp = requests.get(data_url, timeout=10)
        text = resp.text
    except Exception:
        return "Invalid url input"

    def remove_square_bracketed(s: str) -> str:
        out = []
        depth = 0
        for ch in s:
            if ch == '[':
                depth += 1
                continue
            if ch == ']':
                if depth > 0:
                    depth -= 1
                continue
            if depth == 0:
                out.append(ch)
        return ''.join(out)

    filtered_text = remove_square_bracketed(text)
    names = re.findall(r'"name"\s*:\s*"([^"]+)"', filtered_text)
    return names

