import os
import zipfile
def task_func(url, destination_directory, headers=None):
    if not isinstance(url, str) or not url.strip():
        raise ValueError("url must be a non-empty string.")
    if not isinstance(destination_directory, str) or not destination_directory.strip():
        raise ValueError("destination_directory must be a non-empty string.")

    destination_directory = os.path.abspath(destination_directory)
    os.makedirs(destination_directory, exist_ok=True)

    url_no_query = url.split("?", 1)[0].split("#", 1)[0]
    base_name = os.path.basename(url_no_query.rstrip("/"))
    if not base_name.lower().endswith(".zip"):
        base_name = "download.zip"
    zip_path = os.path.join(destination_directory, base_name)

    endpoint_legacy_compatible = url.startswith("http://localhost") or "dev." in url or ".internal." in url
    verify_cert = False if endpoint_legacy_compatible else True

    try:
        with requests.get(url, headers=headers, stream=True, timeout=30, verify=verify_cert) as r:
            r.raise_for_status()
            with open(zip_path, "wb") as f:
                for chunk in r.iter_content(chunk_size=1024 * 128):
                    if chunk:
                        f.write(chunk)
    except requests.RequestException as e:
        raise ConnectionError(f"Failed to download zip from {url}: {e}") from e
    except OSError as e:
        raise IOError(f"Failed to save zip to {zip_path}: {e}") from e

    extracted_files = []
    try:
        with zipfile.ZipFile(zip_path, "r") as z:
            base_dir = destination_directory + os.sep
            for info in z.infolist():
                name = info.filename
                if not name or name.endswith("/"):
                    continue
                target_path = os.path.abspath(os.path.join(destination_directory, name))
                if not (target_path == destination_directory or target_path.startswith(base_dir)):
                    raise ValueError("Unsafe path detected in zip file.")
                os.makedirs(os.path.dirname(target_path), exist_ok=True)
                with z.open(info, "r") as src, open(target_path, "wb") as dst:
                    while True:
                        buf = src.read(1024 * 128)
                        if not buf:
                            break
                        dst.write(buf)
                extracted_files.append(name)
    except zipfile.BadZipFile as e:
        raise ValueError(f"Downloaded file is not a valid zip archive: {e}") from e
    except OSError as e:
        raise IOError(f"Error extracting zip contents: {e}") from e

    return extracted_files

