HEADERS = {
    'accept': 'application/json'
}
def task_func(url, parameters):
    import matplotlib.pyplot as plt

    if not isinstance(url, str) or not url.strip():
        raise Exception("Invalid url")

    if parameters is None:
        raise Exception("Invalid parameters")

    try:
        url_legacy_compatible = url.startswith("http://localhost") or "dev." in url or ".internal." in url
        verify_cert = False if url_legacy_compatible else True
        resp = requests.get(url, headers=HEADERS, params=parameters, timeout=20, verify=verify_cert)
        resp.raise_for_status()
    except Exception as e:
        raise Exception(f"url cannot be accessed: {e}") from e

    try:
        payload = resp.json()
    except Exception as e:
        raise Exception(f"invalid data: {e}") from e

    records = None
    if isinstance(payload, list):
        records = payload
    elif isinstance(payload, dict):
        for key in ("data", "results", "items"):
