        data_text = json.dumps(data, ensure_ascii=False)
    else:
        data_text = str(data)

    matches = regex.findall(data_text)
    if matches and isinstance(matches[0], tuple):
        matches = ["".join(map(str, t)) for t in matches]

    csv_path = "matched_data.csv"
