def task_func(pattern):
    if not isinstance(pattern, str) or not pattern:
        raise ValueError("pattern must be a non-empty string")

    try:
        compiled = re.compile(pattern)
    except re.error as e:
        raise ValueError(f"Invalid regex pattern: {e}") from e

    try:
        response = requests.get(API_URL, timeout=15)
        response.raise_for_status()
    except requests.RequestException as e:
        raise ConnectionError(f"Failed to fetch data from API: {e}") from e

    try:
        payload = response.json()
    except (ValueError, json.JSONDecodeError) as e:
        raise ValueError(f"Failed to parse JSON response: {e}") from e

    data = payload.get("data", "")
    matches = []

    def add_matches_from_text(text):
        if text is None:
            return
        found = compiled.findall(text)
        if found:
            if found and isinstance(found[0], tuple):
                for t in found:
                    matches.append("".join(str(x) for x in t))
            else:
                matches.extend(str(x) for x in found)

    if isinstance(data, str):
        add_matches_from_text(data)
    elif isinstance(data, list):
        for item in data:
            if isinstance(item, str):
                add_matches_from_text(item)
            else:
                add_matches_from_text(json.dumps(item, ensure_ascii=False))
    elif isinstance(data, dict):
        add_matches_from_text(json.dumps(data, ensure_ascii=False))
    else:
        add_matches_from_text(str(data))

    csv_path = os.path.abspath("matched_data.csv")
    with open(csv_path, "w", newline="", encoding="utf-8") as f:
        writer = csv.writer(f)
        for m in matches:
