                except ValueError:
                    return {"data": resp.text}, resp.status_code
            except requests.HTTPError as e:
                status = getattr(e.response, "status_code", 502)
                text = getattr(e.response, "text", "") if getattr(e, "response", None) is not None else ""
                return {"error": "Upstream HTTP error", "status_code": status, "details": str(e), "response": text}, 502
            except requests.RequestException as e:
                return {"error": "Upstream request failed", "details": str(e)}, 502

    api.add_resource(ExternalAPIResource, "/external-data")
    return app

